 public static async Task<int> Run(){var count=0;void Check(bool value,string label){if(!value)throw new Exception(label);count++;Console.WriteLine("PASS connection tools: "+label);}
 var source=new ConnectionProfile{Name="Production template",Host="private.example.invalid",Username="private-user",Authentication="key",KeyId="secret-reference",PasswordId="password-reference",Notes="private notes",StartupCommands="do not run",JumpHost="private-jump",Environment="produzione",Port=2222};
 // An SSH profile cannot carry local startup commands; construction itself never runs them.
 source.StartupCommands="";source.StartupMacro=null;source.Hooks=[new("before-connect","local",Path.Combine(Environment.SystemDirectory,"cmd.exe"),["/c","do not run"],true)];source.Tunnels=[new("fixture","local",1234,"localhost",22,true)];
 source.Operations=new(){Contact="private contact",Maintenance="private maintenance",Checklist=[new(Guid.NewGuid().ToString("N"),"private task")]};
 var template=ConnectionTemplate.Create(source,"Reusable SSH");var serialized=JsonSerializer.Serialize(template,ProfileStore.Json);Check(!serialized.Contains("private contact")&&!serialized.Contains("private maintenance")&&!serialized.Contains("private task"),"connection templates exclude operational notes and checklists");Check(!serialized.Contains(source.Host)&&!serialized.Contains(source.Username)&&!serialized.Contains("secret-reference")&&!serialized.Contains("password-reference")&&!serialized.Contains(source.Notes),"template stores no endpoint, user, credential reference or notes");
 var profile=template.Instantiate(true,true);Check(profile.Id!=source.Id&&profile.Host==""&&profile.Username==""&&profile.KeyId==""&&profile.PasswordId==""&&profile.Authentication=="password","new connection requires its own endpoint and explicit credential selection");Check(profile.Port==2222&&profile.Environment=="produzione","selected network and environment settings are reusable");Check(profile.JumpHost==""&&profile.Hooks.Count==0&&profile.Tunnels.Count==0&&profile.StartupMacro==null&&profile.StartupCommands==""&&profile.Native.ArgumentsJson=="[]"&&profile.Native.ConfigFile==""&&profile.Native.IdentityFile==""&&profile.Native.Executable=="","templates cannot silently enable commands, routes or external identity files");var defaults=template.Instantiate(false,false);Check(defaults.Port==22&&defaults.Environment=="sviluppo"&&defaults.Id!=profile.Id,"deselected groups use safe defaults and each instantiation gets a fresh identity");
 foreach(var invalid in new[]{template with{Name=""},template with{Port=0},template with{Id="invalid"},template with{Protocol="unknown"},template with{TimeoutSeconds=0}}){try{invalid.Instantiate(true,true);throw new Exception("Invalid template accepted");}catch(InvalidDataException){Check(true,"malformed stored template is rejected before use");}}
 var native=ConnectionTemplate.Create(new(){Name="Native",Protocol="native",Native=new(){Kind="ssh",Target="private-alias",ConfigFile=Path.Combine(Path.GetTempPath(),"private-config")}},"Native template").Instantiate(true,true);Check(native.Protocol=="native"&&native.Native.Kind=="ssh"&&native.Native.Target==""&&native.Native.ConfigFile=="","native templates preserve the client kind without an executable target or config");
 var root=Directory.CreateTempSubdirectory("relay-template-");try{var store=new ProfileStore(root.FullName);var operational=new ConnectionProfile{Name="Operational fixture",Host="fixture.invalid",Username="fixture",Notes="Instructions <script> are text",Operations=new(){Contact="Team fixture",Maintenance="Maintenance fixture",Checklist=[new(Guid.NewGuid().ToString("N"),"Verify change window",true)]}};var savedView=new ConnectionSearchView(Guid.NewGuid(),"Fixture view","fixture.invalid");var data=new AppData{ConnectionViews=[savedView],ConnectionTemplates=[template],Profiles=[operational]};store.Save(data);var loaded=store.Load();Check(loaded.ConnectionViews.Single()==savedView,"saved searches persist within the selected account");Check(loaded.Profiles.Single().Operations.Checklist.Single().Completed&&loaded.Profiles.Single().Notes==operational.Notes,"operational notes and completed checklist survive account-store reload");Check(loaded.ConnectionTemplates.Single()==template,"templates persist within the selected account configuration");using(var vault=new KeyVault(Path.Combine(root.FullName,"keys.vault"))){vault.Unlock("Synthetic template fixture password 923!");var portable=VaultSyncCrypto.Capture(vault,data,[]);Check(VaultSyncCrypto.Parse(portable).Version==2,"new encrypted snapshots explicitly declare application schema two");var unknown=System.Text.Json.Nodes.JsonNode.Parse(portable)!;unknown["data"]!["unsupportedFutureField"]=true;try{VaultSyncCrypto.Parse(JsonSerializer.SerializeToUtf8Bytes(unknown));throw new Exception("Unknown schema-two field dropped");}catch(JsonException){Check(true,"unknown schema-two metadata is refused rather than silently discarded");}Check(VaultSyncCrypto.Parse(portable).Data.ConnectionViews.Single()==savedView,"saved connection queries remain inside encrypted archive synchronization");Check(VaultSyncCrypto.Parse(portable).Data.Profiles.Single().Operations.Maintenance==operational.Operations.Maintenance&&VaultSyncCrypto.Parse(portable).Data.Profiles.Single().Operations.Checklist.Single().Text=="Verify change window","encrypted archive synchronization preserves operational metadata as data");Check(VaultSyncCrypto.Parse(portable).Data.ConnectionTemplates.Single()==template,"encrypted archive snapshot preserves validated templates without credential references");}var import=Path.Combine(root.FullName,"import.json");File.WriteAllText(import,JsonSerializer.Serialize(new AppData(),ProfileStore.Json));store.Import(import,data);Check(store.Load().ConnectionTemplates.Single()==template,"profile import preserves existing account templates");}finally{root.Delete(true);}
 foreach(var invalidViews in new[]{new[]{new ConnectionSearchView(Guid.Empty,"Invalid","")},new[]{new ConnectionSearchView(Guid.NewGuid(),"Invalid",new string('x',201))},Enumerable.Range(0,31).Select(i=>new ConnectionSearchView(Guid.NewGuid(),"View "+i,"")).ToArray()}){try{ConnectionSearchView.Validate(invalidViews);throw new Exception("Invalid saved view accepted");}catch(InvalidDataException){Check(true,"saved search identifiers, query length and count are bounded");}}
 foreach(var invalidOperations in new[]{new ConnectionOperations{Contact=new string('x',1001)},new ConnectionOperations{Checklist=[new("invalid","Task")]},new ConnectionOperations{Checklist=[new(Guid.Empty.ToString(),"Task")]},new ConnectionOperations{Checklist=Enumerable.Range(0,31).Select(_=>new OperationalTask(Guid.NewGuid().ToString(),"Task")).ToList()}}){try{invalidOperations.Validate();throw new Exception("Invalid operational notes accepted");}catch(ArgumentException){Check(true,"invalid or oversized operational metadata is rejected");}}
 var listener=new TcpListener(IPAddress.Loopback,0);listener.Start();try{var port=((IPEndPoint)listener.LocalEndpoint).Port;var probing=ConnectionProbe.Run(new(){Name="Probe fixture",Host="127.0.0.1",Username="fixture",Port=port},CancellationToken.None);using var accepted=await listener.AcceptTcpClientAsync();var result=await probing;var buffer=new byte[1];using var deadline=new CancellationTokenSource(TimeSpan.FromSeconds(3));Check(await accepted.GetStream().ReadAsync(buffer,deadline.Token)==0,"probe closes the socket without sending credentials or protocol data");Check(result.Steps.Any(step=>step.Stage=="tcp"&&step.Status=="passed")&&result.Steps.Any(step=>step.Stage=="authentication"&&step.Status=="not-tested"),"TCP success remains distinct from authentication and server identity");}finally{listener.Stop();}
 var skipped=await ConnectionProbe.Run(source,CancellationToken.None);Check(skipped.Steps.Single().Status=="skipped","jump-host routes are never replaced with an unauthorized direct probe");using var cancelled=new CancellationTokenSource();cancelled.Cancel();try{await ConnectionProbe.Run(new(){Name="Cancel fixture",Host="127.0.0.1",Username="fixture"},cancelled.Token);throw new Exception("Cancelled probe ran");}catch(OperationCanceledException){Check(true,"cancelled session prevents a probe");}Check(ProductionFilePolicy.RequiresConfirmation(source,2),"production file changes require explicit confirmation");Check(!ProductionFilePolicy.RequiresConfirmation(source with{Environment="test"},1),"test environments do not receive a production warning");Check(ProductionFilePolicy.RequiresConfirmation(source with{Environment=" Production "},1),"imported English production labels retain the guard");var searchTime=DateTime.UtcNow;Check(new RemoteSearchQuery("/",Name:"MATCH",Extension:".LoG",MinimumBytes:10,MaximumBytes:20,ModifiedAfter:searchTime.AddMinutes(-1),ModifiedBefore:searchTime.AddMinutes(1)).Matches("match.log",14,searchTime),"remote search matches bounded name extension size and date filters");Check(!new RemoteSearchQuery("/",Name:".*").Matches("file.log",14,searchTime),"search names are literal strings rather than executable regular expressions");foreach(var invalidSearch in new[]{new RemoteSearchQuery("/",MinimumBytes:20,MaximumBytes:10),new RemoteSearchQuery("/",MaximumDepth:17),new RemoteSearchQuery("/",MaximumEntries:20001),new RemoteSearchQuery("/",Extension:"../bad"),new RemoteSearchQuery("/",MaximumResults:1001),new RemoteSearchQuery("/",ModifiedAfter:searchTime,ModifiedBefore:searchTime.AddDays(-1))}){try{invalidSearch.Validate();throw new Exception("Invalid search accepted");}catch(ArgumentException){Check(true,"invalid remote search bounds and filters are rejected");}}Check(SshSession.CapacityBytes(10,4096)==40960&&SshSession.CapacityBytes(ulong.MaxValue,4096)==null&&SshSession.CapacityBytes(10,0)==null,"remote filesystem capacity refuses overflow and unknown block size");Check(new[]{"CON","con.txt","LPT9.log","com¹.csv","NUL.","CONOUT$"}.All(WindowsFileNames.IsReserved)&&new[]{"console.txt","company.txt","LPT0.txt","COM10.log"}.All(name=>!WindowsFileNames.IsReserved(name)),"Windows device names are rejected without rejecting ordinary filenames");var preferenceSource=new UserSettings(Language:"en",AppMusicEnabled:false,AppMusicVolume:.2,SyncLanguage:true,SyncMusic:true,RequireAppAuthentication:true,ExternalEditor:@"C:\Private\editor.exe",MeteredConnection:true);var portablePreferences=PortablePreferences.Capture(preferenceSource,new());var preferenceJson=JsonSerializer.Serialize(portablePreferences,ProfileStore.Json);Check(!preferenceJson.Contains("Private")&&!preferenceJson.Contains("requireAppAuthentication")&&!preferenceJson.Contains("meteredConnection"),"portable preferences include no editor paths authentication or metered settings");var preferenceTarget=new UserSettings(Language:"it",AutoLockMinutes:3,SyncLanguage:true,SyncMusic:true,ExternalEditor:@"C:\Target\editor.exe",CloseToTray:true,MeteredConnection:true);var appliedPreferences=portablePreferences.Apply(preferenceTarget);Check(appliedPreferences.Language=="en"&&!appliedPreferences.AppMusicEnabled&&appliedPreferences.AppMusicVolume==.2&&appliedPreferences.AutoLockMinutes==3&&appliedPreferences.ExternalEditor==preferenceTarget.ExternalEditor&&appliedPreferences.CloseToTray&&appliedPreferences.MeteredConnection,"opt-in applies only selected portable fields and preserves device security settings");Check(portablePreferences.Apply(new UserSettings()).Language=="it"&&portablePreferences.Apply(new UserSettings()).AppMusicEnabled,"an opted-out receiver keeps its own language and audio");Check(PortablePreferences.Capture(new UserSettings(),portablePreferences)==portablePreferences,"opting out preserves the last encrypted preference copy for other devices");foreach(var invalidPreferences in new[]{new PortablePreferences("invalid"),new PortablePreferences(Music:new(true,double.NaN)),new PortablePreferences(Music:new(true,1.1))}){try{invalidPreferences.Validate();throw new Exception("Invalid preferences accepted");}catch(Exception error)when(error is ArgumentException or InvalidDataException){Check(true,"malformed portable preference values are refused");}}Console.WriteLine("Connection tool checks: "+count);return 0;
 }
